function prim(graph, start) {
  const visited = new Set();
  const pq = [[0, start]];
  let cost = 0;
  while (pq.length) {
    pq.sort((a, b) => a[0] - b[0]);
    const [w, node] = pq.shift();
    if (visited.has(node)) continue;
    visited.add(node);
    cost += w;
    for (const [next, weight] of graph[node]) {
      if (!visited.has(next)) pq.push([weight, next]);
    }
  }
  return cost;
}

