int primMST(vector<vector<int>>& g) {
    int n = g.size();
    vector<int> key(n, INT_MAX);
    vector<bool> inMST(n, false);
    priority_queue<pair<int, int>, vector<pair<int, int>>, greater<>> pq;
    key[0] = 0;
    pq.push({0, 0});
    int total = 0;
    while (!pq.empty()) {
        auto [d, u] = pq.top();
        pq.pop();
        if (inMST[u]) continue;
        inMST[u] = true;
        total += d;
        for (int v = 0; v < n; v++) if (g[u][v] && !inMST[v] && g[u][v] < key[v]) {
            key[v] = g[u][v];
            pq.push({key[v], v});
        }
    }
    return total;
}

